const data = $input.first().json;

// Extract Groq response from Basic LLM Chain
let raw = data.text ?? data.output ?? data.response;

if (typeof raw !== "string" || !raw.trim()) {
  throw new Error("Groq returned an empty response.");
}

// Remove Markdown JSON formatting
raw = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Extract and parse JSON
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("Valid JSON not found in Groq response.");
}

const result = JSON.parse(raw.substring(start, end + 1));

// Get original ticket code
const triggerData =
  $("When Executed by Another Workflow").first().json;

const ticketCode =
  triggerData.ticket_code ||
  triggerData.context?.ticket_code;

if (!ticketCode) {
  throw new Error("Ticket code missing from Routing input.");
}

// Validate routing result
const department = result.route_to || result.department;

if (!department || !result.reason || !result.priority) {
  throw new Error("Required routing information missing.");
}

// Return output
return [{
  json: {
    ticket_code: ticketCode,
    request_type: result.request_type,
    department: department,
    route_to: department,
    priority: result.priority,
    reason: result.reason,
    status: result.status || "Open"
  }
}];
